39	    @Mapping(target = "initials", expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" + owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
40	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
41	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
42	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
43	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
44	    @Mapping(target = "locality", expression = "java(locality(owner))")
45	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
46	    @Mapping(target = "bulkSignupWarning", expression = "java(bulkSignupWarning(owner))")
47	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
48	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
49	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
50	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
51	    public abstract OwnerDto toOwnerDto(Owner owner);
52	
53	    /**
54	     * The month the fiscal year starts on (1 July).
55	     */
56	    private static final int FISCAL_YEAR_START_MONTH = 7;
57	
58	    /**
59	     * Derives the fiscal year (as an integer) of the given date. The fiscal year starts on 1 July,
60	     * so a date on or after 1 July belongs to the following calendar year's fiscal year (e.g.
61	     * 2026-07-01 is fiscal year 2027) while an earlier date takes the calendar year unchanged.
62	     */
63	    private int fiscalYearOf(LocalDate date) {
64	        return date.getMonthValue() >= FISCAL_YEAR_START_MONTH ? date.getYear() + 1 : date.getYear();
65	    }
66	
67	    /**
68	     * Derives the owner's {@code fiscalYear}, formatted {@code FY<YY>} where YY is the last two
69	     * digits of the fiscal year (starting 1 July) of the owner's business-day-adjusted
70	     * {@code registrationDate}. Returns {@code null} when no registration date is present.
71	     */
72	    protected String fiscalYear(Owner owner) {
73	        LocalDate registrationDate = owner.getRegistrationDate();
74	        if (registrationDate == null) {
75	            return null;
76	        }
77	        return String.format("FY%02d", fiscalYearOf(registrationDate) % 100);
78	    }
79	
80	    /**
81	     * Derives the owner's {@code ageBand} from their {@code birthDate} relative to their
82	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} from 18 to 64, and
83	     * {@code SENIOR} at 65 or older. Returns {@code null} when no birth date was supplied, or when
84	     * the registration date (against which the age is measured) is absent.
85	     */
86	    protected OwnerDto.AgeBandEnum ageBand(Owner owner) {
87	        LocalDate birthDate = owner.getBirthDate();
88	        LocalDate registrationDate = owner.getRegistrationDate();
89	        if (birthDate == null || registrationDate == null) {
90	            return null;
91	        }
92	        int age = Period.between(birthDate, registrationDate).getYears();
93	        if (age < 18) {
94	            return OwnerDto.AgeBandEnum.MINOR;
95	        }
96	        if (age < 65) {
97	            return OwnerDto.AgeBandEnum.ADULT;
98	        }
99	        return OwnerDto.AgeBandEnum.SENIOR;
100	    }
101	
102	    /**
103	     * The country calling codes (without the leading {@code '+'}) the display formatter recognises,
104	     * longest first so the correct code is matched before a shorter prefix of it. Australia
105	     * ({@code +61}) and the North American Numbering Plan ({@code +1}) mirror the codes the create
106	     * endpoint normalizes against.
107	     */
108	    private static final List<String> KNOWN_COUNTRY_CODES = List.of("61", "1");
109	
110	    /**
111	     * Derives the owner's {@code telephoneDisplay}: the stored E.164 {@code telephone} formatted for
112	     * humans as the country code, a space, then the national digits grouped in threes (e.g.
113	     * {@code +61412345678} becomes {@code +61 412 345 678}). Returns the raw value unchanged when it
114	     * is {@code null} or not an E.164 number ({@code '+'} followed by digits).
115	     */
116	    protected String telephoneDisplay(Owner owner) {
117	        String telephone = owner.getTelephone();
118	        if (telephone == null || !telephone.matches("\\+[0-9]+")) {
119	            return telephone;
120	        }
121	        String digits = telephone.substring(1);
122	        String countryCode = KNOWN_COUNTRY_CODES.stream()
123	            .filter(digits::startsWith)
124	            .findFirst()
125	            .orElse("");
126	        String national = digits.substring(countryCode.length());
127	        StringBuilder grouped = new StringBuilder();
128	        for (int i = 0; i < national.length(); i++) {
129	            if (i > 0 && i % 3 == 0) {
130	                grouped.append(' ');
131	            }
132	            grouped.append(national.charAt(i));
133	        }
134	        return "+" + countryCode + " " + grouped;
135	    }
136	
137	    /**
138	     * Derives the owner's {@code identityKey}, the single consolidated duplicate-detection key:
139	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. A {@code null}
140	     * email or householdId contributes an empty segment.
141	     */
142	    protected String identityKey(Owner owner) {
143	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
144	        String email = owner.getEmail() == null ? "" : owner.getEmail();
145	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
146	        return telephone + "|" + email + "|" + householdId;
147	    }
148	
149	    /**
150	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email address is
151	     * present, otherwise {@code PHONE}.
152	     */
153	    protected OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
154	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
155	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
156	    }
157	
158	    /**
159	     * The inclusive 4-digit postcode range that identifies each region, keyed by region code
160	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
161	     */
162	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
163	        "NSW", new int[] {2000, 2099},
164	        "VIC", new int[] {3000, 3099},
165	        "QLD", new int[] {4000, 4099});
166	
167	    /**
168	     * Derives the owner's locality (region) from the region-and-hash identity: it is the REGION
169	     * component of the owner's {@code customerCode} ({@code <REGION>-<HASH8>}), so the locality now
170	     * moves in lockstep with the identity assigned on create. When no customer code has been
171	     * assigned (e.g. seed data) the region is derived directly, preferring the postcode: a 4-digit
172	     * postcode falling in a known region's range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099)
173	     * yields that region, otherwise the city-to-region table (Sydney->NSW, Melbourne->VIC,
174	     * Brisbane->QLD) is consulted, returning {@code UNKNOWN} when neither identifies a region.
175	     */
176	    protected String locality(Owner owner) {
177	        String customerCode = owner.getCustomerCode();
178	        if (customerCode != null) {
179	            int dash = customerCode.indexOf('-');
180	            if (dash > 0) {
181	                return customerCode.substring(0, dash);
182	            }
183	        }
184	        String fromPostcode = regionFromPostcode(owner.getPostcode());
185	        if (fromPostcode != null) {
186	            return fromPostcode;
187	        }
188	        String city = owner.getCity();
189	        if (city == null) {
190	            return "UNKNOWN";
191	        }
192	        return switch (city) {
193	            case "Sydney" -> "NSW";
194	            case "Melbourne" -> "VIC";
195	            case "Brisbane" -> "QLD";
196	            default -> "UNKNOWN";
197	        };
198	    }
199	
200	    /**
201	     * The IANA timezone of each region, keyed by region code (NSW->Australia/Sydney,
202	     * VIC->Australia/Melbourne, QLD->Australia/Brisbane).
203	     */
204	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
205	        "NSW", "Australia/Sydney",
206	        "VIC", "Australia/Melbourne",
207	        "QLD", "Australia/Brisbane");
208	
209	    /**
210	     * Derives the owner's {@code timezone}: the IANA timezone name for the owner's
211	     * {@link #locality(Owner) locality/region}, looked up in the fixed region-to-timezone table
212	     * (NSW->Australia/Sydney, VIC->Australia/Melbourne, QLD->Australia/Brisbane). Returns
213	     * {@code null} when the region has no known timezone (e.g. {@code UNKNOWN}).
214	     */
215	    protected String timezone(Owner owner) {
216	        return REGION_TIMEZONE.get(locality(owner));
217	    }
218	
219	    /**
220	     * Resolves the region whose postcode range contains the given postcode, or {@code null} when
221	     * the postcode is absent, not 4 digits, or in no known range.
222	     */
223	    private String regionFromPostcode(String postcode) {
224	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
225	            return null;
226	        }
227	        int value = Integer.parseInt(postcode);
228	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
229	            int[] range = entry.getValue();
230	            if (value >= range[0] && value <= range[1]) {
231	                return entry.getKey();
232	            }
233	        }
234	        return null;
235	    }
236	
237	    /**
238	     * The minimum household size (counting the owner itself) that earns household membership
239	     * points.
240	     */
241	    private static final int HOUSEHOLD_POINTS_SIZE = 3;
242	
243	    /**
244	     * An owner's tenure must span strictly more than this many elapsed fiscal years to earn the
245	     * tenure membership points. A newly created owner has zero elapsed fiscal years and so never
246	     * clears this threshold.
247	     */
248	    private static final int TENURE_POINTS_FISCAL_YEARS = 1;
249	
250	    /**
251	     * Derives the owner's membership points: it starts at 0, gains 2 when an email is present,
252	     * gains 1 when the owner has no namesakes (namesakeCount is 0), gains 2 when the owner's
253	     * household has {@value #HOUSEHOLD_POINTS_SIZE} or more members, and gains 3 once the owner's
254	     * tenure exceeds {@value #TENURE_POINTS_FISCAL_YEARS} elapsed fiscal year(s).
255	     */
256	    protected Integer membershipPoints(Owner owner) {
257	        int points = 0;
258	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
259	        if (hasEmail) {
260	            points += 2;
261	        }
262	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
263	        if (noNamesakes) {
264	            points += 1;
265	        }
266	        if (householdSize(owner) >= HOUSEHOLD_POINTS_SIZE) {
267	            points += 2;
268	        }
269	        if (tenureFiscalYears(owner) > TENURE_POINTS_FISCAL_YEARS) {
270	            points += 3;
271	        }
272	        return points;
273	    }
274	
275	    /**
276	     * Derives the owner's membership level from their {@link #membershipPoints(Owner) membership
277	     * points}: level 1 for 0-1 points, level 2 for 2-3, level 3 for 4-5, and level 4 for 6 or more.
278	     */
279	    protected Integer membershipLevel(Owner owner) {
280	        int points = membershipPoints(owner);
281	        if (points <= 1) {
282	            return 1;
283	        }
284	        if (points <= 3) {
285	            return 2;
286	        }
287	        if (points <= 5) {
288	            return 3;
289	        }
290	        return 4;
291	    }
292	
293	    /**
294	     * The number of owners in this owner's household — the count of owners (including this one)
295	     * sharing its {@code householdId}. Returns 0 when the owner has no household identifier.
296	     */
297	    private long householdSize(Owner owner) {
298	        String householdId = owner.getHouseholdId();
299	        if (householdId == null) {
300	            return 0;
301	        }
302	        return this.clinicService.findAllOwners().stream()
303	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
304	            .count();
305	    }
306	
307	    /**
308	     * The owner's tenure in elapsed fiscal years: the number of fiscal years (each starting 1 July)
309	     * between their {@code registrationDate} and the current date, i.e. the current fiscal year less
310	     * the registration date's fiscal year. Returns 0 when no registration date is present, so an
311	     * owner without a registration date is treated as having no tenure.
312	     */
313	    private long tenureFiscalYears(Owner owner) {
314	        LocalDate registrationDate = owner.getRegistrationDate();
315	        if (registrationDate == null) {
316	            return 0;
317	        }
318	        return (long) fiscalYearOf(LocalDate.now()) - fiscalYearOf(registrationDate);
319	    }
320	
321	    /**
322	     * Flags a bulk-signup day: {@code true} once more than {@link #BULK_SIGNUP_THRESHOLD} other
323	     * owners already carry this owner's {@code registrationDate}. The owner itself is excluded from
324	     * the count, so on a create the flag reflects the owners that pre-existed it that day, matching
325	     * the accumulation the per-day create limit is enforced against. Returns {@code false} when the
326	     * owner has no registration date.
327	     */
328	    protected Boolean bulkSignupWarning(Owner owner) {
329	        LocalDate registrationDate = owner.getRegistrationDate();
330	        if (registrationDate == null) {
331	            return false;
332	        }
333	        long othersOnDay = this.clinicService.findAllOwners().stream()
334	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
335	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
336	            .count();
337	        return othersOnDay > BULK_SIGNUP_THRESHOLD;
338	    }
339	
340	    /**
341	     * Derives the owner's {@code checkDigit}: the Luhn check digit (0-9) computed over the digits
342	     * contained in the owner's {@code customerCode}. Non-digit characters are ignored. Returns
343	     * {@code null} when no customer code has been assigned.
344	     */
345	    protected Integer checkDigit(Owner owner) {
346	        String customerCode = owner.getCustomerCode();
347	        if (customerCode == null) {
348	            return null;
349	        }
350	        int sum = 0;
351	        boolean dbl = true;
352	        for (int i = customerCode.length() - 1; i >= 0; i--) {
353	            char c = customerCode.charAt(i);
354	            if (c < '0' || c > '9') {
355	                continue;
356	            }
357	            int d = c - '0';
358	            if (dbl) {
359	                d *= 2;
360	                if (d > 9) {
361	                    d -= 9;
362	                }
363	            }
364	            sum += d;
365	            dbl = !dbl;
366	        }
367	        return (10 - (sum % 10)) % 10;
368	    }
369	
370	    /**
371	     * Derives the owner's {@code salutation}: the owner's {@code title} and {@code lastName}
372	     * separated by a single space (e.g. {@code DR Franklin}), or just the {@code lastName} when no
373	     * title was supplied (a {@code null} or blank title).
374	     */
375	    protected String salutation(Owner owner) {
376	        String title = owner.getTitle();
377	        String lastName = owner.getLastName();
378	        if (title == null || title.isBlank()) {
379	            return lastName;
380	        }
381	        return title + " " + lastName;
382	    }
383	
384	    /**
385	     * Derives the owner's {@code selfLink}: the canonical link to this owner resource, formatted
386	     * {@code /api/owners/<id>} using the owner's id. Returns {@code null} when the owner has no id.
387	     */
388	    protected String selfLink(Owner owner) {
389	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
390	    }
391	
392	    public abstract Owner toOwner(OwnerDto ownerDto);
393	
394	    @Mapping(target = "id", ignore = true)
395	    @Mapping(target = "pets", ignore = true)
396	    public abstract Owner toOwner(OwnerFieldsDto ownerDto);
397	
398	    public abstract List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
399	
400	    public abstract Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
401	
402	    public OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
403	        OwnerPageDto ownerPageDto = new OwnerPageDto();
404	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
405	        ownerPageDto.setPage(ownerPage.getNumber());
406	        ownerPageDto.setSize(ownerPage.getSize());
407	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
408	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
409	        return ownerPageDto;
410	    }
411	}
