77	@RestController
78	@CrossOrigin(exposedHeaders = "errors, content-type")
79	@RequestMapping("/api")
80	public class OwnerRestControllerV1 implements OwnersApi {
81	
82	    /**
83	     * Matches a syntactically valid email: a non-empty local part and domain separated by a single
84	     * '@', with at least one dot-separated label in the domain and no whitespace anywhere.
85	     */
86	    private static final Pattern EMAIL_PATTERN =
87	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
88	
89	    /**
90	     * Email domains rejected as disposable/throwaway addresses. An owner whose email domain matches
91	     * one of these (compared case-insensitively) is rejected with 400.
92	     */
93	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
94	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
95	
96	    /**
97	     * Dedicated audit logger. On a successful owner create an audit line is emitted carrying the
98	     * new owner's id, customerCode, registrationDate, membershipLevel and membershipNumber.
99	     */
100	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
101	
102	    /**
103	     * Common street-type abbreviations expanded during address normalization, keyed by the
104	     * upper-cased abbreviation.
105	     */
106	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
107	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
108	
109	    /**
110	     * Maximum number of owners a single city may contain. A create is rejected once the owner's
111	     * city already holds this many owners.
112	     */
113	    private static final int CITY_CAPACITY = 50;
114	
115	    /**
116	     * Maximum number of owners that may be created on a single day. A create is rejected once this
117	     * many owners already carry the current day as their {@code registrationDate}.
118	     */
119	    private static final int DAILY_OWNER_LIMIT = 100;
120	
121	    /**
122	     * Fixed public holidays that the business-day roll skips: when an adjusted registration date lands
123	     * on one of these it advances to the next non-holiday business day.
124	     */
125	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
126	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
127	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"), LocalDate.parse("2026-12-28"));
128	
129	    private final ClinicService clinicService;
130	
131	    private final OwnerMapper ownerMapper;
132	
133	    private final PetMapper petMapper;
134	
135	    private final VisitMapper visitMapper;
136	
137	    /**
138	     * Remembers the id of the owner created under each seen {@code Idempotency-Key}, so a create that
139	     * repeats with an already-seen key returns the originally created owner instead of creating a
140	     * duplicate.
141	     */
142	    private final Map<String, Integer> ownersByIdempotencyKey = new ConcurrentHashMap<>();
143	
144	    public OwnerRestControllerV1(ClinicService clinicService,
145	                                 OwnerMapper ownerMapper,
146	                                 PetMapper petMapper,
147	                                 VisitMapper visitMapper) {
148	        this.clinicService = clinicService;
149	        this.ownerMapper = ownerMapper;
150	        this.petMapper = petMapper;
151	        this.visitMapper = visitMapper;
152	    }
153	
154	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
155	    @Override
156	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
157	        Collection<Owner> owners;
158	        if (lastName != null) {
159	            owners = this.clinicService.findOwnerByLastName(lastName);
160	        } else {
161	            owners = this.clinicService.findAllOwners();
162	        }
163	        if (owners.isEmpty()) {
164	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
165	        }
166	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
167	    }
168	
169	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
170	    @Override
171	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
172	        Owner owner = this.clinicService.findOwnerById(ownerId);
173	        if (owner == null) {
174	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
175	        }
176	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
177	    }
178	
179	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
180	    @Override
181	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
182	        String idempotencyKey = currentIdempotencyKey();
183	        if (idempotencyKey != null) {
184	            Integer existingId = ownersByIdempotencyKey.get(idempotencyKey);
185	            if (existingId != null) {
186	                Owner existing = this.clinicService.findOwnerById(existingId);
187	                if (existing != null) {
188	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
189	                }
190	            }
191	        }
192	        validateRequiredFields(ownerFieldsDto);
193	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
194	        HttpHeaders headers = new HttpHeaders();
195	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
196	        applyAddress(owner, ownerFieldsDto);
197	        rejectFutureRegistrationDate(owner.getRegistrationDate());
198	        LocalDate effectiveDate = owner.getRegistrationDate() == null
199	            ? LocalDate.now()
200	            : owner.getRegistrationDate();
201	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
202	        rejectWhenDailyLimitReached(owner.getRegistrationDate());
203	        rejectWhenCityAtCapacity(owner.getCity());
204	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
205	        applyHousehold(owner, sharesHousehold);
206	        owner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
207	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
208	        rejectDuplicateIdentity(owner);
209	        owner.setCustomerCode(customerCode(owner));
210	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
211	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
212	        flagPossibleDuplicate(owner, sharesHousehold);
213	        this.clinicService.saveOwner(owner);
214	        if (idempotencyKey != null) {
215	            ownersByIdempotencyKey.put(idempotencyKey, owner.getId());
216	        }
217	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
218	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
219	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
220	            ownerDto.getMembershipLevel(), owner.getMembershipNumber());
221	        headers.setLocation(UriComponentsBuilder.newInstance()
222	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
223	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
224	    }
225	
226	    /**
227	     * Reads the {@code Idempotency-Key} header of the request currently being handled, returning
228	     * {@code null} when the header is absent or blank (or there is no bound request). A non-blank
229	     * value opts the create into idempotent replay via {@link #ownersByIdempotencyKey}.
230	     *
231	     * @return the trimmed idempotency key, or {@code null} when none was supplied
232	     */
233	    private String currentIdempotencyKey() {
234	        if (!(RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attrs)) {
235	            return null;
236	        }
237	        String key = attrs.getRequest().getHeader("Idempotency-Key");
238	        return isBlank(key) ? null : key.trim();
239	    }
240	
241	    /**
242	     * Builds the owner's customer code, formatted {@code <REGION>-<HASH8>} where REGION is the region
243	     * code derived from the owner's postcode (falling back to the city-to-region table, then
244	     * {@code UNKNOWN}) and HASH8 is the first 8 upper-cased hex characters of the SHA-256 of the
245	     * owner's normalized telephone concatenated with its last name (e.g. {@code NSW-1A2B3C4D}).
246	     *
247	     * <p>Should the computed code collide with an existing owner's {@code customerCode}, it is
248	     * de-duplicated by appending {@code -<n>} with the smallest {@code n} of 2 or more that makes it
249	     * unique (e.g. {@code NSW-1A2B3C4D-2}), so distinct owners always receive distinct customer codes.
250	     *
251	     * @param owner the owner being created, with its normalized telephone already applied
252	     * @return the assigned, de-duplicated customer code
253	     */
254	    private String customerCode(Owner owner) {
255	        String base = regionCode(owner) + "-" + identityHash8(owner.getTelephone(), owner.getLastName());
256	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
257	            .map(Owner::getCustomerCode)
258	            .filter(code -> code != null)
259	            .collect(java.util.stream.Collectors.toSet());
260	        if (!existingCodes.contains(base)) {
261	            return base;
262	        }
263	        int n = 2;
264	        while (existingCodes.contains(base + "-" + n)) {
265	            n++;
266	        }
267	        return base + "-" + n;
268	    }
269	
270	    /**
271	     * Derives the region code embedded in an owner's customer code, preferring the postcode: a
272	     * 4-digit postcode falling in a known region's range (NSW 2000-2099, VIC 3000-3099,
273	     * QLD 4000-4099) yields that region. Otherwise the city-to-region table (Sydney->NSW,
274	     * Melbourne->VIC, Brisbane->QLD) is consulted, returning {@code UNKNOWN} when neither the
275	     * postcode nor the city identifies a region.
276	     *
277	     * @param owner the owner being created
278	     * @return the derived region code, never {@code null}
279	     */
280	    private String regionCode(Owner owner) {
281	        String fromPostcode = regionFromPostcode(owner.getPostcode());
282	        if (fromPostcode != null) {
283	            return fromPostcode;
284	        }
285	        String fromCity = region(owner.getCity());
286	        return fromCity == null ? "UNKNOWN" : fromCity;
287	    }
288	
289	    /**
290	     * Resolves the region whose postcode range contains the given postcode, or {@code null} when the
291	     * postcode is absent, not 4 digits, or in no known range.
292	     *
293	     * @param postcode the owner's postcode, may be {@code null}
294	     * @return the region code, or {@code null} when no known range contains the postcode
295	     */
296	    private String regionFromPostcode(String postcode) {
297	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
298	            return null;
299	        }
300	        int value = Integer.parseInt(postcode);
301	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
302	            int[] range = entry.getValue();
303	            if (value >= range[0] && value <= range[1]) {
304	                return entry.getKey();
305	            }
306	        }
307	        return null;
308	    }
309	
310	    /**
311	     * Computes the identity hash embedded in an owner's customer code: the first 8 upper-cased hex
312	     * characters of the SHA-256 of the owner's normalized telephone concatenated with its last name.
313	     *
314	     * @param telephone the owner's normalized (E.164) telephone
315	     * @param lastName  the owner's last name
316	     * @return the 8-character upper-cased hex hash
317	     */
318	    private String identityHash8(String telephone, String lastName) {
319	        String input = (telephone == null ? "" : telephone) + (lastName == null ? "" : lastName);
320	        try {
321	            byte[] digest = MessageDigest.getInstance("SHA-256")
322	                .digest(input.getBytes(StandardCharsets.UTF_8));
323	            StringBuilder hex = new StringBuilder(digest.length * 2);
324	            for (byte b : digest) {
325	                hex.append(String.format("%02x", b));
326	            }
327	            return hex.substring(0, 8).toUpperCase(Locale.ROOT);
328	        } catch (NoSuchAlgorithmException ex) {
329	            throw new IllegalStateException("SHA-256 not available", ex);
330	        }
331	    }
332	
333	    /**
334	     * Builds the owner's membership number, formatted {@code <customerCode>-M<YY>} where YY is the
335	     * last two digits of the fiscal year of the owner's business-day-adjusted registration date,
336	     * zero-padded (e.g. {@code NSW-1A2B3C4D-M26}). The fiscal year starts on 1 July.
337	     *
338	     * @param customerCode     the owner's assigned customer code
339	     * @param registrationDate the owner's business-day-adjusted registration date
340	     * @return the assigned membership number
341	     */
342	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
343	        return String.format("%s-M%02d", customerCode, fiscalYear(registrationDate) % 100);
344	    }
345	
346	    /**
347	     * The month the fiscal year starts on (1 July).
348	     */
349	    private static final int FISCAL_YEAR_START_MONTH = 7;
350	
351	    /**
