379	    /**
380	     * Flags an owner as a possible (soft) duplicate. Although it is not a hard duplicate (its whole
381	     * {@link #identityKey(Owner) identityKey} is unique, so the create was not rejected), it may
382	     * still resemble an existing owner: when it shares an existing owner's lastName (compared
383	     * case-insensitively) and postcode while carrying a different telephone, the owner is flagged
384	     * with {@code possibleDuplicate=true} and {@code possibleDuplicateOf} set to that existing
385	     * owner's id. When no such owner exists the flag is set to {@code false} and no match id is
386	     * recorded. An owner with no postcode can never soft-match and is always {@code false}.
387	     *
388	     * <p>A declared household member (created with {@code sharesHousehold=true}) is never a suspected
389	     * duplicate: its match with an existing household member is a deliberate, declared one, so it is
390	     * always flagged {@code false}.
391	     *
392	     * @param owner           the owner being created, with its normalized telephone already applied
393	     * @param sharesHousehold whether the request declared it shares a household; a declared member is
394	     *                        never flagged as a possible duplicate
395	     */
396	    private void flagPossibleDuplicate(Owner owner, boolean sharesHousehold) {
397	        Owner match = sharesHousehold ? null : findPossibleDuplicate(owner);
398	        if (match != null) {
399	            owner.setPossibleDuplicate(true);
400	            owner.setPossibleDuplicateOf(match.getId());
401	        } else {
402	            owner.setPossibleDuplicate(false);
403	            owner.setPossibleDuplicateOf(null);
404	        }
405	    }
