408	     * Finds the existing owner this owner soft-matches: same lastName (case-insensitive) and same
409	     * postcode, but a different telephone. When several existing owners match, the one with the
410	     * lowest id is chosen so the result is deterministic. Returns {@code null} when the owner has no
411	     * postcode or no such existing owner exists.
412	     *
413	     * @param owner the owner being created
414	     * @return the matching existing owner, or {@code null} when there is no soft-match
415	     */
416	    private Owner findPossibleDuplicate(Owner owner) {
417	        if (isBlank(owner.getPostcode())) {
418	            return null;
419	        }
420	        return this.clinicService.findAllOwners().stream()
421	            .filter(existing -> equalsIgnoreCase(existing.getLastName(), owner.getLastName())
422	                && owner.getPostcode().equals(existing.getPostcode())
423	                && !equalsIgnoreCase(existing.getTelephone(), owner.getTelephone()))
424	            .min(Comparator.comparing(Owner::getId))
425	            .orElse(null);
