562	    /**
563	     * Validates an owner's postcode, but only when one is supplied. A {@code null} or blank postcode
564	     * is optional and accepted, keeping the create contract backward-compatible. When present the
565	     * value must be 4 digits and, when the owner's city has a known region (Sydney->NSW,
566	     * Melbourne->VIC, Brisbane->QLD), must fall within that region's inclusive range (NSW 2000-2099,
567	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
568	     *
569	     * @param postcode the raw postcode value as submitted, may be {@code null}
570	     * @param city     the owner's city, used to resolve the region whose range applies
571	     * @throws InvalidPostcodeException if a supplied postcode is not 4 digits or is out of range for
572	     *                                  the city's region
573	     */
574	    private void validatePostcode(String postcode, String city) {
575	        if (isBlank(postcode)) {
576	            return;
577	        }
578	        if (!postcode.matches("[0-9]{4}")) {
579	            throw new InvalidPostcodeException(postcode, city);
580	        }
581	        String region = region(city);
582	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
583	        if (range != null) {
584	            int value = Integer.parseInt(postcode);
585	            if (value < range[0] || value > range[1]) {
586	                throw new InvalidPostcodeException(postcode, city);
587	            }
588	        }
589	    }
