592	     * Derives an owner's region from its city using the fixed city-to-region table (Sydney->NSW,
593	     * Melbourne->VIC, Brisbane->QLD), returning {@code null} when the city is not in the table.
594	     *
595	     * @param city the owner's city
596	     * @return the region code, or {@code null} when the city has no known region
597	     */
598	    private String region(String city) {
599	        if (city == null) {
600	            return null;
601	        }
602	        return switch (city) {
603	            case "Sydney" -> "NSW";
604	            case "Melbourne" -> "VIC";
605	            case "Brisbane" -> "QLD";
606	            default -> null;
