610	    /**
611	     * The number of national (subscriber) digits an E.164 number must carry for a given country
612	     * calling code, keyed by that code (without the leading '+'). Australia ('+61') requires 9
613	     * national digits and the North American Numbering Plan ('+1') requires 10.
614	     */
615	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
616	        Map.of("61", 9, "1", 10);
617	
618	    /**
619	     * Normalizes a submitted telephone into E.164 form. Spaces, dashes and brackets are stripped.
620	     * A leading '+' with its country code is kept; otherwise the country code '+61' is assumed and
621	     * a single leading '0' is dropped from the national digits. The resulting value must be a '+'
622	     * followed by 8 to 15 digits, and its national-number length must match the one required by its
623	     * country calling code ('+61' requires 9 national digits, '+1' requires 10).
624	     *
625	     * @param telephone the raw telephone value as submitted
626	     * @return the E.164 normalized telephone (e.g. {@code +61412345678})
627	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number, or its
628	     *                                   national-number length is wrong for its country code
629	     */
630	    private String normalizeTelephone(String telephone) {
631	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
632	        String nationalSignificantNumber;
633	        if (cleaned.startsWith("+")) {
634	            nationalSignificantNumber = cleaned.substring(1);
635	        } else {
636	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
637	            nationalSignificantNumber = "61" + national;
638	        }
639	        if (!nationalSignificantNumber.matches("[0-9]{8,15}")) {
640	            throw new InvalidTelephoneException(telephone);
641	        }
642	        validateNationalNumberLength(nationalSignificantNumber, telephone);
643	        return "+" + nationalSignificantNumber;
644	    }
645	
646	    /**
647	     * Validates the national-number length of an E.164 number against its country calling code. The
648	     * significant number is a country code immediately followed by the national digits; for each
649	     * known code in {@link #NATIONAL_NUMBER_LENGTHS} the remaining national digits must number
650	     * exactly the required amount ('+61' requires 9, '+1' requires 10). Codes with no known rule are
651	     * left unchecked.
652	     *
653	     * @param nationalSignificantNumber the E.164 digits following the '+' (country code + national)
654	     * @param rejectedValue             the raw telephone value, reported on rejection
655	     * @throws InvalidTelephoneException if the national-number length is wrong for the country code
656	     */
657	    private void validateNationalNumberLength(String nationalSignificantNumber, String rejectedValue) {
658	        for (Map.Entry<String, Integer> rule : NATIONAL_NUMBER_LENGTHS.entrySet()) {
659	            String countryCode = rule.getKey();
660	            if (nationalSignificantNumber.startsWith(countryCode)) {
661	                int nationalDigits = nationalSignificantNumber.length() - countryCode.length();
662	                if (nationalDigits != rule.getValue()) {
663	                    throw new InvalidTelephoneException(rejectedValue);
664	                }
665	                return;
666	            }
667	        }
668	    }
