670	    /**
671	     * Normalizes a submitted email. An owner may omit the email entirely (a {@code null} or blank
672	     * value is treated as absent and returns {@code null}); when present the value must be a
673	     * syntactically valid address, and is stored and returned lower-cased.
674	     *
675	     * @param email the raw email value as submitted, may be {@code null}
676	     * @return the lower-cased email, or {@code null} when none was supplied
677	     * @throws InvalidEmailException if a non-blank value is not a syntactically valid address
678	     */
679	    private String normalizeEmail(String email) {
680	        if (email == null || email.isBlank()) {
681	            return null;
682	        }
683	        String normalized = email.trim().toLowerCase();
684	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
685	            throw new InvalidEmailException(email);
686	        }
687	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
688	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
689	            throw new DisposableEmailException(email);
690	        }
691	        return normalized;
692	    }
