859	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
860	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
861	        if (currentOwner == null) {
862	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
863	        }
864	        currentOwner.setAddress(ownerFieldsDto.getAddress());
865	        currentOwner.setCity(ownerFieldsDto.getCity());
866	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
867	        currentOwner.setLastName(ownerFieldsDto.getLastName());
868	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
869	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
870	        this.clinicService.saveOwner(currentOwner);
871	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
872	    }
873	
874	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
875	    @Transactional
876	    @Override
877	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
878	        Owner owner = this.clinicService.findOwnerById(ownerId);
879	        if (owner == null) {
880	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
881	        }
882	        owner.setDeleted(true);
883	        this.clinicService.saveOwner(owner);
884	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
885	    }
886	
887	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
888	    @Override
889	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
890	        Owner owner = this.clinicService.findOwnerById(ownerId);
891	        if (owner == null) {
892	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
893	        }
894	        HttpHeaders headers = new HttpHeaders();
895	        Pet pet = petMapper.toPet(petFieldsDto);
896	        owner.setId(ownerId);
897	        pet.setOwner(owner);
898	        pet.getType().setName(null);
899	        this.clinicService.savePet(pet);
900	        PetDto petDto = petMapper.toPetDto(pet);
901	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
902	            .buildAndExpand(pet.getId()).toUri());
903	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
904	    }
905	
906	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
907	    @Override
908	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
909	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
910	        if (currentOwner != null) {
911	            Pet currentPet = this.clinicService.findPetById(petId);
912	            if (currentPet != null) {
913	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
914	                currentPet.setName(petFieldsDto.getName());
915	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
916	                this.clinicService.savePet(currentPet);
917	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
918	            }
919	        }
920	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
921	    }
922	
923	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
924	    @Override
925	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
926	        HttpHeaders headers = new HttpHeaders();
927	        Visit visit = visitMapper.toVisit(visitFieldsDto);
928	        Pet pet = new Pet();
929	        pet.setId(petId);
930	        visit.setPet(pet);
931	        this.clinicService.saveVisit(visit);
932	        VisitDto visitDto = visitMapper.toVisitDto(visit);
933	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
934	            .buildAndExpand(visit.getId()).toUri());
935	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
936	    }
937	
938	
939	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
940	    @Override
941	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
942	        Owner owner = this.clinicService.findOwnerById(ownerId);
943	        if (owner != null) {
944	            Pet pet = owner.getPet(petId);
945	            if (pet != null) {
946	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
947	            }
948	        }
949	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
950	    }
951	}
